# ITEM 1: FREEZE CURRENT REELS BASELINE
# Gather all SHA and deployment info in parallel
echo "=== ITEM 1: BASELINE FREEZE ==="

# 1. GitHub HEAD
TOKEN=$(cat /tmp/owner_token.txt 2>/dev/null || echo "")
if [ -z "$TOKEN" ]; then
  echo "RE-AUTHING OWNER..."
  TOKEN=$(curl -sS -X POST https://ivx-holdings-platform.onrender.com/api/ivx/owner-passwordless-login \
    -H "Content-Type: application/json" \
    -d '{"email":"iperez4242@gmail.com","emergency":"ivx_emergency_recovery"}' 2>/dev/null | bun -e 'const d=JSON.parse(await Bun.stdin.text());console.log(d.accessToken||"")' 2>/dev/null)
  echo "$TOKEN" > /tmp/owner_token.txt
  echo "TOKEN_REFRESHED: ${TOKEN:0:8}...${TOKEN: -4}"
else
  echo "TOKEN_CACHED: ${TOKEN:0:8}...${TOKEN: -4}"
fi

echo ""
echo "--- GitHub HEAD ---"
curl -sS -X POST https://ivx-holdings-platform.onrender.com/api/ivx/developer-deploy/action \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer $TOKEN" \
  -d '{"action":"github_get_repo_head","confirm":true,"confirmText":"","input":{"branch":"main"}}' 2>&1 | bun -e '
const d=JSON.parse(await Bun.stdin.text());
console.log("headSha:", d.result?.headSha);
console.log("headMsg:", d.result?.headCommitMessage?.split("\n")[0]);
console.log("headAuthor:", d.result?.headCommitAuthor);
console.log("headDate:", d.result?.headCommitDate);
console.log("httpStatus:", d.result?.httpStatus);
' 2>/dev/null

echo ""
echo "--- Production Health ---"
curl -sS https://ivx-holdings-platform.onrender.com/health 2>&1 | bun -e '
const d=JSON.parse(await Bun.stdin.text());
console.log("status:", d.status);
console.log("commit:", d.seniorDeveloperRuntime?.commitSha);
console.log("bootTime:", d.seniorDeveloperRuntime?.bootTime || d.seniorDeveloperRuntime?.checkedAt);
console.log("environment:", d.seniorDeveloperRuntime?.environment || d.environment);
console.log("version:", d.seniorDeveloperRuntime?.version || d.version);
console.log("renderServiceId:", d.seniorDeveloperRuntime?.renderServiceId || "N/A");
' 2>/dev/null

echo ""
echo "--- Production /version ---"
curl -sS https://ivx-holdings-platform.onrender.com/version 2>&1 | bun -e '
const d=JSON.parse(await Bun.stdin.text());
console.log("version:", d.version || d.commit || "N/A");
console.log("commit:", d.commit || d.commitSha || "N/A");
console.log("buildTimestamp:", d.buildTimestamp || "N/A");
' 2>/dev/null

