const handleTap = useCallback(() => {
  if (data.mediaType !== 'video') return;
  const now = Date.now();
  if (now - lastTapRef.current < 320) {
    lastTapRef.current = 0;
    setShowHeart(true);
    setTimeout(() => setShowHeart(false), 800);
    handleDoubleTapLike();
  } else {
    lastTapRef.current = now;
    setTimeout(() => {
      if (lastTapRef.current === now) {
        setPaused((p) => !p);
      }
    }, 330);
  }
}, []);

