FIRST_ID=$(curl -sS "https://ivx-holdings-platform.onrender.com/api/ivx/video-platform/admin/videos" -H "Authorization: Bearer $TOKEN" 2>/dev/null | bun -e 'const d=JSON.parse(await Bun.stdin.text());const vids=d.videos||d.data||[];console.log(vids[0]?.id||"none")' 2>/dev/null)
echo "Testing toggle on video: $FIRST_ID"
if [ "$FIRST_ID" != "none" ] && [ -n "$FIRST_ID" ]; then
  curl -sS -X PATCH "https://ivx-holdings-platform.onrender.com/api/ivx/video-platform/admin/videos/$FIRST_ID" -H "Authorization: Bearer $TOKEN" -H "Content-Type: application/json" -d '{"is_featured":true}' 2>&1 | bun -e '
const d = JSON.parse(await Bun.stdin.text());
console.log("toggle_result:", d.ok ? "ok" : "fail");
console.log("featured:", d.video?.is_featured);
' 2>/dev/null
fi

