   245| * video's project_id against jv_deals.id. Falls back to fuzzy title/project-name
   246| * matching because project_videos.project_id is often the video's own UUID, not the
   247| * deal slug. Returns a map keyed by videoId. Never throws; missing deals → null.
   248| */
   249|async function loadFeedDeals(sb: any, candidates: string[], titles: Record<string, string>): Promise<Record<string, FeedDeal>> {
   250|  const out: Record<string, FeedDeal> = {};
   251|  const idRe = /^[A-Za-z0-9][A-Za-z0-9_-]{1,63}$/;
   252|  const ids = Array.from(new Set(candidates.filter((c) => idRe.test(c))));
   253|  const allDeals: any[] = [];
   254|
   255|  try {
   256|    const { data } = await sb
   257|      .from('jv_deals')
   258|      .select('id,title,project_name,estimated_value,appraised_value,total_investment,min_investment,expected_roi,type')
   259|      .limit(200);
   260|    for (const d of data ?? []) {
   261|      const id = String(d.id);
   262|      const deal: FeedDeal = {
   263|        id,
   264|        title: d.title ?? d.project_name ?? null,
   265|        price: d.estimated_value ?? d.appraised_value ?? d.total_investment ?? null,
   266|        min_investment: d.min_investment ?? null,
   267|        expected_roi: d.expected_roi != null ? String(d.expected_roi) : null,
   268|        deal_type: d.type ?? null,
   269|        url: `https://ivxholding.com/?deal=${id}#deals`,
   270|      };
   271|      allDeals.push({ ...d, __deal: deal });
   272|      // Exact match by id: assign to any video whose candidate id matches the deal id
   273|      if (ids.includes(id)) {
   274|        for (const p of Object.entries(titles)) {
   275|          const [videoId, _title] = p;
   276|          if (!out[videoId]) out[videoId] = deal;
   277|        }
   278|      }
   279|    }
   280|
   281|    // Fuzzy fallback: match video titles against deal title/project_name.
   282|    for (const [videoId, title] of Object.entries(titles)) {
   283|      if (out[videoId] || !title) continue;
   284|      const t = title.toLowerCase();
   285|      const words = t.split(/[^a-z0-9]+/).filter((w) => w.length > 2);
   286|      let best: { deal: FeedDeal; score: number } | null = null;
   287|      for (const d of allDeals) {
   288|        const dealTitle = String(d.title ?? d.project_name ?? '').toLowerCase();
   289|        const dealName = String(d.project_name ?? '').toLowerCase();
   290|        const matches = words.filter((w) => dealTitle.includes(w) || dealName.includes(w)).length;
   291|        const score = matches / Math.max(words.length, 1);
   292|        if (score >= 0.3 && (!best || score > best.score)) {
